#include <iostream>
#include <iomanip>

int main() {
    // C++14/C++17 integer literal prefixes
    const int dec_val = 42;       // Base 10
    const int bin_val = 0b101010; // Base 2 (0b prefix)
    const int oct_val = 052;      // Base 8 (leading 0 prefix)
    const int hex_val = 0x2A;     // Base 16 (0x prefix)

    std::cout << "Decimal: " << dec_val << "\n";
    std::cout << "Binary literal value in decimal: " << bin_val << "\n";
    std::cout << "Octal literal value in decimal: " << oct_val << "\n";
    std::cout << "Hex literal value in decimal: " << hex_val << "\n";

    // Output formatting using std::oct and std::hex
    std::cout << "Output as Octal: " << std::oct << dec_val << "\n";
    std::cout << "Output as Hex: " << std::hex << std::uppercase << dec_val << "\n";

    return 0;
}

#include <iostream>
#include <string_view>

// Evaluates an integer from string representation and base
constexpr unsigned long long evaluate_positional(std::string_view s, unsigned int base) {
    unsigned long long result = 0;
    for (char c : s) {
        unsigned int val = 0;
        if (c >= '0' && c <= '9') {
            val = static_cast<unsigned int>(c - '0');
        } else if (c >= 'A' && c <= 'F') {
            val = static_cast<unsigned int>(c - 'A' + 10);
        } else if (c >= 'a' && c <= 'f') {
            val = static_cast<unsigned int>(c - 'a' + 10);
        }
        result = result * base + val;
    }
    return result;
}

int main() {
    std::cout << "Binary 101 in base 10: " << evaluate_positional("101", 2) << "\n";
    std::cout << "Octal 425 in base 10: " << evaluate_positional("425", 8) << "\n";
    std::cout << "Hex 3DA in base 10: " << evaluate_positional("3DA", 16) << "\n";
    return 0;
}

#include <iostream>
#include <iomanip>
#include <string>
#include <bitset>

int main() {
    // C++17 integer literal notations with digit separators
    unsigned int val_hex = 0x8D1;
    unsigned int val_oct = 04321;
    unsigned int val_bin = 0b1000'1101'0001;

    std::cout << "Equality check: " 
              << ((val_hex == val_oct && val_oct == val_bin) ? "MATCH" : "MISMATCH") 
              << "\n";

    // Expanding FAD5 (hex) to 16-bit binary
    unsigned int fad5 = 0xFAD5;
    std::bitset<16> b_fad5(fad5);
    std::cout << "Hex FAD5 in binary: " << b_fad5 << "\n";

    // Expanding 653 (octal) to 9-bit binary
    unsigned int oct653 = 0653;
    std::bitset<9> b_oct653(oct653);
    std::cout << "Octal 653 in binary: " << b_oct653 << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>
#include <string>
#include <vector>

// Demonstrating the positional column conversion algorithm from Section D.5
std::string decimalToBase(unsigned int decimal, unsigned int base) {
    if (decimal == 0) return "0";
    const char digits[] = "0123456789ABCDEF";

    // 1. Find the highest power of base <= decimal
    unsigned int power = 1;
    while (power <= decimal / base) {
        power *= base;
    }

    // 2. Divide and collect symbols from leftmost column to right
    std::string result;
    unsigned int remainder = decimal;
    while (power > 0) {
        unsigned int digit = remainder / power;
        remainder %= power;
        result.push_back(digits[digit]);
        power /= base;
    }
    return result;
}

int main() {
    // Verifying examples from Fig. D.8, D.9, D.10
    unsigned int b_val = 0b110101;
    unsigned int o_val = 07614;
    unsigned int h_val = 0xAD3B;

    std::cout << "Fig D.8 (110101 to dec): " << b_val << "\n";
    std::cout << "Fig D.9 (7614 oct to dec): " << o_val << "\n";
    std::cout << "Fig D.10 (AD3B hex to dec): " << h_val << "\n";

    // Verifying examples from Section D.5
    std::cout << "57 dec to binary: " << decimalToBase(57, 2) << "\n";
    std::cout << "103 dec to octal: " << decimalToBase(103, 8) << "\n";
    std::cout << "375 dec to hex: " << decimalToBase(375, 16) << "\n";

    return 0;
}
